<template><div><div class="row" style="justify-content:space-between"><div><h1>Mijozlar</h1><p class="muted">Bemorlar ma’lumotlari va shartnoma holati.</p></div><button class="btn primary" @click="openAdd">+ Mijoz</button></div><div class="card"><input v-model="search" class="input" placeholder="Ism, familiya, telefon yoki ish joyi" @input="load"><div style="overflow:auto"><table class="table"><thead><tr><th>F.I.Sh.</th><th>Telefon</th><th>Manzil</th><th>Ish joyi</th><th>Shartnoma</th><th></th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td>{{p.lastName}} {{p.firstName}} {{p.middleName||''}}</td><td>{{p.phone||'—'}}</td><td>{{p.address||'—'}}</td><td>{{p.workplace||'—'}}</td><td>{{p.contract?.contractNo||'—'}} <span v-if="p.contract?.remaining!==undefined" class="muted">({{money(p.contract.remaining)}})</span></td><td><button class="btn" @click="edit(p)">Tahrirlash</button></td></tr></tbody></table></div></div><div v-if="show" class="modal"><div class="modal-box"><h2>{{editing?'Mijozni tahrirlash':'Yangi mijoz'}}</h2><input v-model="form.lastName" class="input" placeholder="Familiya"><input v-model="form.firstName" class="input" placeholder="Ism"><input v-model="form.middleName" class="input" placeholder="Sharif"><input v-model="form.phone" class="input" placeholder="Telefon"><input v-model="form.address" class="input" placeholder="Manzil"><input v-model="form.workplace" class="input" placeholder="Ish joyi"><div class="row"><button class="btn primary" @click="save">Saqlash</button><button class="btn" @click="show=false">Bekor</button></div></div></div></div></template>
<script setup lang="ts">const {request}=useApi();const search=ref('');const rows=ref<any[]>([]);const show=ref(false),editing=ref<any>(null);const form=ref<any>({lastName:'',firstName:'',middleName:'',phone:'',address:'',workplace:''});const money=(n:number)=>new Intl.NumberFormat('uz-UZ').format(n);const load=async()=>rows.value=await request('/patients?search='+encodeURIComponent(search.value));onMounted(load);const openAdd=()=>{editing.value=null;form.value={lastName:'',firstName:'',middleName:'',phone:'',address:'',workplace:''};show.value=true};const edit=(p:any)=>{editing.value=p;form.value={...p};show.value=true};const save=async()=>{if(editing.value)await request('/patients/'+editing.value.id,{method:'PATCH',body:form.value});else await request('/patients',{method:'POST',body:form.value});show.value=false;await load()}</script>
